package app.snaptocart.scan;
import app.snaptocart.config.AppProperties; import com.fasterxml.jackson.databind.*; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.math.BigDecimal; import java.util.*;
@Component public class OpenAiVisionProvider implements VisionProvider { private final AppProperties p; private final ObjectMapper mapper; private final RestClient http=RestClient.create(); public OpenAiVisionProvider(AppProperties p,ObjectMapper m){this.p=p;mapper=m;} public boolean demoMode(){return p.demoMode()||p.openaiApiKey()==null||p.openaiApiKey().isBlank();} public List<VisionProduct> recognize(byte[] image,String media){if(demoMode())return List.of(new VisionProduct("Simple Truth","Country Style Chicken Breakfast Sausage","Fully Cooked","8 oz",.98,"011110038948",new BigDecimal("4.99")));String data="data:"+media+";base64,"+Base64.getEncoder().encodeToString(image);Map<String,Object> body=Map.of("model",p.openaiModel(),"input",List.of(Map.of("role","user","content",List.of(Map.of("type","input_text","text","Identify every grocery package. Return JSON only as {products:[{brand,name,variant,size,confidence}]}"),Map.of("type","input_image","image_url",data)))));JsonNode n=http.post().uri("https://api.openai.com/v1/responses").header("Authorization","Bearer "+p.openaiApiKey()).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(JsonNode.class);try{String text=n.path("output").get(0).path("content").get(0).path("text").asText();JsonNode products=mapper.readTree(text).path("products");List<VisionProduct> out=new ArrayList<>();for(JsonNode x:products)out.add(new VisionProduct(x.path("brand").asText(),x.path("name").asText(),x.path("variant").asText(null),x.path("size").asText(null),x.path("confidence").asDouble(.8),null,null));return out;}catch(Exception e){throw new IllegalStateException("Could not parse vision response",e);} } }
